import CryptoKit
import XCTest
@testable import AustialCastProtocol

/// Verifies the Swift implementation against vectors generated by the Kotlin receiver. If these
/// pass, a Mac sender and an Android receiver agree byte-for-byte on keys, proofs and framing.
final class GoldenVectorsTests: XCTestCase {
    private static func loadVectors() throws -> [String: String] {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("protocol-vectors/vectors.json")
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode([String: String].self, from: data)
    }

    private func vec(_ key: String) throws -> Data {
        let v = try Self.loadVectors()
        return try XCTUnwrap(Data(hex: try XCTUnwrap(v[key], "missing \(key)")))
    }

    func testPlainFrameBytes() throws {
        let (a, b) = MemoryTransport.makePair()
        let w = FrameWriter(transport: a)
        try w.write(.ping, Data([0xaa, 0xbb]))
        XCTAssertEqual(a.written, try vec("plainFrameHex"))
        _ = b
    }

    func testPublicKeysAndSharedSecret() throws {
        let a = try TVCrypto.Ephemeral(scalar: vec("scalarA"))
        let b = try TVCrypto.Ephemeral(scalar: vec("scalarB"))
        XCTAssertEqual(a.publicX963, try vec("publicA"))
        XCTAssertEqual(b.publicX963, try vec("publicB"))
        XCTAssertEqual(try TVCrypto.ecdh(a, peerX963: b.publicX963), try vec("sharedSecret"))
        XCTAssertEqual(try TVCrypto.ecdh(b, peerX963: a.publicX963), try vec("sharedSecret"))
    }

    func testTranscriptHash() throws {
        let t = TVCrypto.transcriptHash(hello: Data("hello-bytes".utf8), challenge: Data("challenge-bytes".utf8))
        XCTAssertEqual(t, try vec("transcript"))
    }

    private func sealedFrame(client: Bool, type: FrameType, payload: Data, skip: Int = 0) throws -> Data {
        let keys = TVCrypto.deriveSessionKeys(shared: try vec("sharedSecret"), transcript: try vec("transcript"))
        let (a, _) = MemoryTransport.makePair()
        let w = FrameWriter(transport: a)
        w.setCipher(client ? keys.clientToServer : keys.serverToClient)
        for _ in 0..<skip { try w.write(.control, try vec("probePlaintext")) }
        let before = a.written.count
        try w.write(type, payload)
        return a.written.suffix(from: before)
    }

    func testSealedFramesMatchKotlin() throws {
        XCTAssertEqual(try sealedFrame(client: true, type: .control, payload: vec("probePlaintext")), try vec("clientToServerKeyProbe"))
        XCTAssertEqual(try sealedFrame(client: false, type: .control, payload: vec("probePlaintext")), try vec("serverToClientKeyProbe"))
        // Second frame on the same cipher uses counter 1.
        XCTAssertEqual(try sealedFrame(client: true, type: .videoFrame, payload: vec("videoPayload"), skip: 1), try vec("secondFrameClientToServer"))
    }

    func testSwiftCanOpenKotlinSealedFrames() async throws {
        let keys = TVCrypto.deriveSessionKeys(shared: try vec("sharedSecret"), transcript: try vec("transcript"))
        let (a, b) = MemoryTransport.makePair()
        try a.write(try vec("serverToClientKeyProbe"))
        let reader = FrameReader(transport: b)
        reader.setCipher(keys.serverToClient)
        let frame = try await reader.read()
        XCTAssertEqual(frame.type, .control)
        XCTAssertEqual(frame.payload, try vec("probePlaintext"))
    }

    func testProofs() throws {
        let t = try vec("transcript")
        let pin = Data("123456".utf8)
        XCTAssertEqual(TVCrypto.clientProof(secret: pin, transcript: t), try vec("clientProofPin"))
        XCTAssertEqual(TVCrypto.serverProof(secret: pin, transcript: t), try vec("serverProofPin"))
        let token = try vec("token")
        XCTAssertEqual(TVCrypto.clientProof(secret: token, transcript: t), try vec("clientProofToken"))
        XCTAssertEqual(TVCrypto.serverProof(secret: token, transcript: t), try vec("serverProofToken"))
    }

    func testMediaPayloadLayout() throws {
        let video = MediaPayload.encodeVideo(keyframe: true, ptsUs: 0x0102030405060708, data: Data([0, 0, 0, 1, 0x65, 9]))
        XCTAssertEqual(video, try vec("videoPayload"))
        let audio = MediaPayload.encodeAudio(ptsUs: 0x1122334455667788, data: Data([1, 2, 3]))
        XCTAssertEqual(audio, try vec("audioPayload"))
    }

    private func jsonObject(_ data: Data) throws -> NSDictionary {
        try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? NSDictionary)
    }

    func testJSONMessagesAreWireCompatible() throws {
        let v = try Self.loadVectors()
        let auth = try JSONEncoder().encode(Auth(mode: "pin", proof: "abcd"))
        XCTAssertEqual(try jsonObject(auth), try jsonObject(Data(v["authJson"]!.utf8)))

        let withAudio = StreamStart(width: 1920, height: 1080, fps: 60, bitrate: 8_000_000,
                                    audio: AudioInfo(sampleRate: 48000, channels: 2, config: "1190"), title: "Display 1")
        XCTAssertEqual(try jsonObject(Messages.encode(withAudio)), try jsonObject(Data(v["streamStartJson"]!.utf8)))
        XCTAssertEqual(try Messages.decode(StreamStart.self, from: Data(v["streamStartJson"]!.utf8)), withAudio)

        let plain = StreamStart(width: 1280, height: 720, fps: 30, bitrate: 4_000_000)
        XCTAssertEqual(try jsonObject(Messages.encode(plain)), try jsonObject(Data(v["streamStartNoAudioJson"]!.utf8)))
    }
}
